// Сборка инструкции для клиента в .docx (конструктор футбольной формы).
// Пересобрать: npm install --no-save docx && node docs/build/make-instruction-docx.cjs
const fs = require('fs');
const path = require('path');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, BorderStyle, LevelFormat
} = require('docx');

const ACCENT = '14294C';
const MUTED = '6B6459';
const LINE = 'DAD0BD';
const WARN = 'FDF2E0';
const TABLE_W = 9360;

const t = (text, opts = {}) => new TextRun({ text, ...opts });
const arr = (x) => (Array.isArray(x) ? x : [t(x)]);
const p = (children, opts = {}) => new Paragraph({ children: arr(children), spacing: { after: 140, line: 276 }, ...opts });
const h1 = (text) => new Paragraph({ text, heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 160 } });
const h2 = (text) => new Paragraph({ text, heading: HeadingLevel.HEADING_2, spacing: { before: 260, after: 120 } });
const code = (text) => t(text, { font: 'Consolas', size: 20, color: ACCENT });

const callout = (children) => new Paragraph({
  children: arr(children),
  spacing: { before: 120, after: 160, line: 276 },
  indent: { left: 220, right: 220 },
  shading: { type: ShadingType.CLEAR, fill: WARN },
  border: {
    top: { style: BorderStyle.SINGLE, size: 2, color: LINE },
    bottom: { style: BorderStyle.SINGLE, size: 2, color: LINE },
    left: { style: BorderStyle.SINGLE, size: 12, color: 'E0922F' },
    right: { style: BorderStyle.SINGLE, size: 2, color: LINE }
  }
});

const cell = (content, opts) => new TableCell({
  width: { size: opts.width, type: WidthType.DXA },
  margins: { top: 90, bottom: 90, left: 140, right: 140 },
  shading: opts.header ? { type: ShadingType.CLEAR, fill: 'F4EFE3' } : undefined,
  children: [new Paragraph({
    children: [t(content, { bold: !!opts.header, color: opts.header ? ACCENT : undefined })],
    spacing: { after: 0 }
  })]
});

const bd = { style: BorderStyle.SINGLE, size: 2, color: LINE };
const table = (widths, rows) => new Table({
  columnWidths: widths,
  width: { size: TABLE_W, type: WidthType.DXA },
  borders: { top: bd, bottom: bd, left: bd, right: bd, insideHorizontal: bd, insideVertical: bd },
  rows: rows.map((cells, i) => new TableRow({
    tableHeader: i === 0,
    children: cells.map((c, j) => cell(c, { width: widths[j], header: i === 0 }))
  }))
});

const bullet = (children) => new Paragraph({ children: arr(children), numbering: { reference: 'dash', level: 0 }, spacing: { after: 90, line: 276 } });
const step = (children) => new Paragraph({ children: arr(children), numbering: { reference: 'steps', level: 0 }, spacing: { after: 90, line: 276 } });

const numbering = { config: [
  { reference: 'dash', levels: [{ level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT,
    style: { paragraph: { indent: { left: 420, hanging: 240 } } } }] },
  { reference: 'steps', levels: [{ level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT,
    style: { paragraph: { indent: { left: 420, hanging: 240 } } } }] }
] };

const styles = { default: {
  document: { run: { font: 'Calibri', size: 22, color: '1B1B1B' } },
  heading1: { run: { font: 'Calibri', size: 30, bold: true, color: ACCENT } },
  heading2: { run: { font: 'Calibri', size: 25, bold: true, color: ACCENT } }
} };

const children = [
  new Paragraph({ children: [t('Конструктор футбольной формы', { bold: true, size: 40, color: ACCENT })], spacing: { after: 60 } }),
  new Paragraph({
    children: [t('Как всё настроить самому, без программиста', { size: 26, color: MUTED })],
    spacing: { after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: LINE, space: 6 } }
  }),
  new Paragraph({ children: [t('Инструкция для администратора jetronsport.ru. Обновлено 29.07.2026.', { size: 20, color: MUTED })], spacing: { after: 260 } }),

  p('Всё, что настраивается, собрано в одном месте: в админке сайта слева есть пункт «Конструктор формы». Внутри четыре вкладки: цены нанесений, размерные сетки, шрифты, модели и цвета. Отдельно живут два инструмента: цена изделия берётся из карточки товара, а рамки нанесений двигаются в редакторе зон прямо на макете.'),
  p([t('Изменения появляются у покупателей сразу после обновления страницы конструктора. ', { bold: true }), t('Ничего перезапускать не нужно.')]),

  h1('1. Цены нанесений'),
  p([t('Админка сайта, пункт '), t('«Конструктор формы»', { bold: true }), t(', вкладка '), t('«Цены нанесений»', { bold: true }), t('.')]),
  p('Здесь задаются надбавки к цене формы: фамилия и номер, номер на груди, логотипы, гетры и скидки. Цену самой формы тут не трогаем, она приходит из карточки товара, об этом раздел 5.'),
  table([3400, 2600, 3360], [
    ['Что настраиваете', 'Единица', 'Пример'],
    ['Фамилия и номер', 'рубли', '600'],
    ['Номер на груди, логотипы', 'рубли', '300'],
    ['Гетры', 'рубли', '450'],
    ['Скидки на нанесение Jetron', 'проценты', '5'],
    ['Логотип на груди бесплатно от', 'штук в заказе', '20']
  ]),
  p(''),
  bullet('Пустое поле означает «не задано»: прежнее значение сохранится, нулём оно не станет.'),
  bullet('Скидки вводите числом процентов: написали 5, покупатель получит скидку 5 процентов.'),
  bullet([t('Кнопка '), t('«Сбросить к значениям по умолчанию»', { bold: true }), t(' под формой возвращает исходные цены.')]),
  callout([t('Проверяйте результат. ', { bold: true }), t('После сохранения откройте конструктор, включите нанесение и убедитесь, что итоговая сумма изменилась так, как вы ожидали.')]),

  h1('2. Размерные сетки'),
  p([t('Вкладка '), t('«Размерные сетки»', { bold: true }), t('. Две таблицы, детская и взрослая. Их видит покупатель по ссылке «Таблица размеров».')]),
  p('Таблица заполняется текстом. Первая строка это заголовки колонок, дальше по строке на размер. Значения разделяются точкой с запятой.'),
  p([code('Размер на бирке ; Рост, см ; Возраст, лет')]),
  p([code('4XS ; 120-128 ; 5-6')]),
  bullet('Число значений в строке должно совпадать с числом заголовков.'),
  bullet('Если где-то ошиблись, страница не сохранит таблицу и напишет номер строки: «Строка 9: 2 значений, а в заголовке 3». Поправьте эту строку и сохраните снова.'),
  bullet('Колонки можно переименовать и добавить новые, главное чтобы во всех строках их было одинаково.'),

  h1('3. Шрифты для фамилии и номера'),
  p([t('Вкладка '), t('«Шрифты»', { bold: true }), t('. Здесь список шрифтов, из которых покупатель выбирает начертание фамилии и номера.')]),
  h2('Как добавить свой шрифт'),
  step('Нажмите «Выберите файл» и укажите файл шрифта: TTF, OTF, WOFF или WOFF2, до 5 МБ.'),
  step('Впишите название, которое увидит покупатель, например «Спартак 2024».'),
  step('Галочка «шрифт поддерживает русские буквы» стоит по умолчанию. Если шрифт только латинский, снимите её.'),
  step('Нажмите «Загрузить шрифт». Он сразу появится в конструкторе в выборе шрифта.'),
  callout([t('Про кириллицу. ', { bold: true }), t('Многие клубные шрифты нарисованы только под латиницу. Без галочки шрифт всё равно добавится, но русская фамилия в нём может выглядеть неаккуратно или не отображаться вовсе. Проверьте в конструкторе на настоящей фамилии.')]),
  p([t('Удалить шрифт: ссылка '), t('«убрать»', { bold: true }), t(' в его строке. Кнопка '), t('«Вернуть исходный список»', { bold: true }), t(' возвращает набор шрифтов, с которым конструктор запускался.')]),
  p('Имя файла можно писать по-русски и с пробелами, сайт сам приведёт его к безопасному виду.'),

  h1('4. Модели и цвета'),
  p([t('Вкладка '), t('«Модели и цвета»', { bold: true }), t('. Это каталог формы: строка это конкретная модель в конкретном цвете, её видит покупатель под макетом.')]),
  h2('Как добавить новую модель или новый цвет'),
  step('Приготовьте фотографию формы: PNG, JPG или WebP, до 8 МБ. Лучше всего прозрачный или ровный фон.'),
  step('Выберите линейку из списка или впишите новую, например Champion.'),
  step('Впишите название цвета так, как его увидит покупатель, например «Изумрудный», и выберите сам цвет для кружка в палитре.'),
  step('Загрузите фото спереди. Фото сзади не обязательно: без него спина покажется тем же кадром.'),
  step('Нажмите «Добавить модель».'),
  callout([t('Сразу после добавления разметьте зоны. ', { bold: true }), t('Новая модель наследует общие рамки нанесения, и на вашей фотографии номер с фамилией почти наверняка сядут мимо. В строке модели есть ссылка «разметить», она открывает редактор зон именно на этой модели. Как править, в разделе 6.')]),
  h2('Полезно знать'),
  bullet([t('Колонка '), t('«Зоны нанесения»', { bold: true }), t(' показывает, размечена модель или нет. У размеченных ссылка «поправить», у остальных «разметить».')]),
  bullet('Если добавить ту же линейку с тем же цветом ещё раз, второй строки не появится: обновятся фотографии. Так удобно менять фото, не удаляя модель.'),
  bullet([t('Ссылка '), t('«убрать»', { bold: true }), t(' удаляет модель из каталога. Если это был последний вариант такого цвета, кружок цвета тоже уйдёт из палитры, чтобы у покупателя не оставалось пустых вариантов.')]),
  bullet([t('Кнопка '), t('«Вернуть исходный каталог моделей и цветов»', { bold: true }), t(' внизу страницы отменяет все ваши добавления и удаления разом.')])
];

children.push(
  h1('5. Цена изделия: из карточки товара'),
  p('Цену самой формы конструктор берёт из обычной карточки товара WooCommerce, в самом конструкторе её нет. Товар подбирается по трём признакам:'),
  table([2400, 3600, 3360], [
    ['Признак', 'Где задаётся в товаре', 'Пример'],
    ['Модель', 'атрибут «Модель»', 'Champion, Winner, Space'],
    ['Цвет', 'атрибут «Цвет»', 'Белый, Синий, Красный'],
    ['Возраст', 'категория товара', '«Взрослая форма» или «Детская форма»']
  ]),
  p(''),
  p([t('Чтобы изменить цену: ', { bold: true }), t('откройте товар, измените цену, сохраните. В конструкторе новая цена появится в течение 10 минут, столько живёт кеш.')]),
  p([t('Чтобы у модели появилась своя цена', { bold: true }), t(', у товара должны быть заполнены оба атрибута, Модель и Цвет, и выбрана категория «Взрослая форма» или «Детская форма». Если товара нет или атрибуты не заполнены, конструктор покажет базовую цену 1280 руб., детская 1090 руб.')]),
  callout([t('Обратите внимание. ', { bold: true }), t('В каталоге пока нет карточек для взрослого Champion, а также для линеек Legend и Venom. Для них показывается базовая цена. Заведите товары с нужными атрибутами, и цены подтянутся сами.')]),

  h1('6. Зоны нанесения: где и какого размера печать'),
  p('Зона это пунктирная рамка на макете: куда ляжет номер, фамилия или логотип. Рамки правятся отдельно для каждой модели.'),
  h2('Как открыть редактор'),
  bullet([t('Из админки: вкладка '), t('«Модели и цвета»', { bold: true }), t(', ссылка '), t('«разметить»', { bold: true }), t(' или '), t('«поправить»', { bold: true }), t(' в строке нужной модели. Откроется сразу она.')]),
  bullet([t('Вручную: '), code('https://jetronsport.ru/constructor/?zones=edit'), t(' в том же браузере, где вы вошли в админку.')]),
  p('Внизу слева появится тёмная панель «Редактор зон».'),
  h2('Как править'),
  bullet('Тяните рамку мышью, чтобы переместить. Тяните за угол, чтобы изменить размер. Номер и фамилия двигаются вместе с рамкой, результат виден сразу.'),
  bullet([t('Нажмите '), t('«Сохранить»', { bold: true }), t('. Появится надпись «Сохранено».')]),
  bullet([t('Кнопка '), t('«Отменить правки»', { bold: true }), t(' возвращает зоны текущей модели к прежнему виду.')]),
  p('Зоны хранятся отдельно для каждой модели, соседние вы не заденете. Покупатели увидят изменения после обновления страницы.'),

  h1('7. Кадрирование мокапа: убрать лишние поля с фотографии'),
  p('Если у фотографии большие пустые поля по краям или изделие смещено, кадр можно поправить.'),
  step([t('В редакторе зон, '), code('?zones=edit'), t(', нажмите '), t('«Кадрировать фон»', { bold: true }), t('.')]),
  step('Двигайте фотографию мышью, а за угловые точки увеличивайте или уменьшайте. Масштаб только пропорциональный, изображение не искажается.'),
  step([t('Нажмите '), t('«Применить кадр»', { bold: true }), t(', затем '), t('«Сохранить»', { bold: true }), t('.')]),

  h1('8. Страница конструктора и меню'),
  p([t('Конструктор встроен в страницу '), t('«Онлайн-конструктор формы»', { bold: true }), t('. Найдите её в разделе Страницы. Внутри один блок с кодом вставки, его лучше не трогать.')]),
  callout([t('Обратите внимание. ', { bold: true }), t('На сайте два разных меню: основное для компьютера и мобильное. Пункт, добавленный в одно меню, во втором не появится. Если добавляете новый раздел, добавьте в оба: Внешний вид, Меню, «Меню основное» и «Меню мобильное».')]),

  h1('Короткая памятка'),
  table([4680, 4680], [
    ['Что нужно', 'Куда идти'],
    ['Изменить цену формы', 'Товары, нужный товар, поле «Цена»'],
    ['Изменить цену нанесения или скидку', 'Конструктор формы, вкладка «Цены нанесений»'],
    ['Поправить таблицу размеров', 'Конструктор формы, вкладка «Размерные сетки»'],
    ['Добавить свой шрифт', 'Конструктор формы, вкладка «Шрифты»'],
    ['Добавить модель или цвет', 'Конструктор формы, вкладка «Модели и цвета»'],
    ['Подвинуть рамку нанесения', 'Ссылка «разметить» у модели, тянуть, «Сохранить»'],
    ['Поправить кадр фотографии', 'Редактор зон, кнопка «Кадрировать фон»'],
    ['Добавить пункт меню', 'Внешний вид, Меню, в оба меню']
  ]),
  p(''),
  p([t('Если что-то повело себя не так, как вы ожидали, напишите мне: разберусь и поправлю.', { color: MUTED })])
);

const doc = new Document({
  creator: 'JetronSport',
  title: 'Конструктор футбольной формы: инструкция для администратора',
  description: 'Как настраивать конструктор формы на jetronsport.ru',
  numbering,
  styles,
  sections: [{
    properties: { page: { margin: { top: 1080, bottom: 1080, left: 1080, right: 1080 } } },
    children
  }]
});

const out = path.join(__dirname, '..', 'Инструкция-конструктор-формы.docx');
Packer.toBuffer(doc).then((buf) => {
  fs.writeFileSync(out, buf);
  console.log('готово:', out, buf.length, 'байт');
});
